<template><section><div class="admin-tabs"><button :class="{active:mode==='events'}" @click="mode='events';page=0;load()">위험 활동</button><button v-if="canSelfie" :class="{active:mode==='selfies'}" @click="mode='selfies';page=0;load()">셀피 심사</button></div><p class="subtle">점수는 프로필 키워드 기반 검토 우선순위이며 사기 확률이 아닙니다. 위험 신호는 사기 확정이 아닙니다. 문맥을 검토한 뒤 조치하세요. 같은 회원·유형의 1분 내 반복 신호는 첫 기록으로 묶습니다.</p><div class="admin-toolbar"><label v-if="mode==='events'"><input type="checkbox" v-model="openOnly" @change="page=0;load()"/>미검토만</label><button class="outlined" @click="load">새로고침</button></div><p v-if="error" role="alert">{{error}}</p><details v-if="mode==='events'" class="profile-risks"><summary>기존 프로필 검토 대상 · {{profiles.length}}명</summary><p v-for="p in profiles" :key="p.userId"><button class="table-name" @click="$emit('member',p.userId)">{{p.nickname}} (#{{p.userId}})</button> · {{p.fraudRiskScore}} / 100 · {{p.latestRiskDetail}}</p></details><section class="admin-panel table-panel"><table><thead><tr><th>회원</th><th>유형 / 상태</th><th>검토 점수</th><th>내용</th><th>일시</th><th>처리</th></tr></thead><tbody><tr v-for="e in rows" :key="e.id"><td><button class="table-name" @click="$emit('member',e.userId)">#{{e.userId}}</button></td><td>{{labels[e.type||e.state]||e.type||e.state}}</td><td>{{e.score==null?'—':e.score+' / 100'}}</td><td class="detail">{{e.detail||e.note||e.challenge}}<small v-if="e.reviewNote">검토: {{e.reviewNote}}</small><small v-if="e.targetId">상대 #{{e.targetId}}</small></td><td>{{date(e.createdAt||e.submittedAt)}}</td><td><button v-if="mode==='events'" class="outlined" :disabled="e.reviewed||!canAct" @click="select(e)">{{e.reviewed?'검토 완료':'검토·조치'}}</button><button v-else class="outlined" :disabled="!e.photosAvailable" @click="select(e)">{{e.photosAvailable?'사진 비교':'사진 파기됨'}}</button></td></tr></tbody></table><p v-if="!rows.length" class="empty">기록이 없습니다.</p><footer class="pagination"><button :disabled="page===0||busy" @click="page--;load()">이전</button>{{page+1}}<button :disabled="rows.length<(mode==='events'?50:30)||busy" @click="page++;load()">다음</button></footer></section><dialog ref="modal" class="admin-dialog"><header><h2>{{mode==='events'?'위험 활동 검토':'셀피 수동 심사'}}</h2><button class="icon-close" :disabled="busy" @click="close">×</button></header><template v-if="selected"><p class="case-body">{{selected.detail||selected.challenge}}</p><p v-if="selected.score!=null">검토 점수 {{selected.score}} / 100 · 사기 확률이 아닙니다.</p><div v-if="mode==='selfies'" class="compare"><figure><img tabindex="0" role="button" title="사진 확대" style="cursor:zoom-in" v-if="reference" :src="reference" alt="제출 당시 대표 사진"/><figcaption>제출 당시 대표 사진</figcaption></figure><figure><img tabindex="0" role="button" title="사진 확대" style="cursor:zoom-in" v-if="selfie" :src="selfie" alt="촬영한 셀피"/><figcaption>셀피 · 요청한 손동작도 확인</figcaption></figure></div><p v-if="mode==='selfies'">자동 일치 점수는 없습니다. 조명·화장 차이만으로 반려하지 마세요. 불확실하면 보완 요청을 선택하세요. 승인해도 신원·생체 인증을 보증하지 않습니다.</p><form @submit.prevent="save"><label v-if="mode==='events'">조치<select v-model="action"><option value="NONE">검토 완료 / 조치 없음</option><option value="WARNING">경고</option><option value="TEMPORARY">기간 정지</option><option value="PERMANENT">영구 정지</option></select></label><label v-else>심사 결과<select v-model="action"><option value="RETRY">보완 요청</option><option value="APPROVED">수동 확인 완료</option></select></label><label v-if="action==='TEMPORARY'">정지 일수<input type="number" min="1" max="365" v-model.number="days" required/></label><label>{{mode==='selfies'&&action==='APPROVED'?'코멘트 (선택)':'검토 사유'}}<textarea v-model="note" :required="mode!=='selfies'||action!=='APPROVED'" maxlength="1000"/></label><p>경고·정지 또는 셀피 보완 요청 사유는 대상 회원에게 안내됩니다.</p><button class="accent" :disabled="busy||((mode!=='selfies'||action!=='APPROVED')&&!note.trim())||(mode==='selfies'&&(selected.state!=='PENDING'||!selfie||!reference))">저장</button></form></template><p v-if="modalError" role="alert">{{modalError}}</p></dialog></section></template>
<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue';import api from '../../api/api';import {adminAccount} from '../../adminSession';
defineEmits(['member']);const profiles=ref([]);const mode=ref('events'),page=ref(0),openOnly=ref(true),rows=ref([]),error=ref(''),modalError=ref(''),busy=ref(false),selected=ref(),modal=ref(),action=ref('NONE'),days=ref(7),note=ref(''),selfie=ref(''),reference=ref('');const canSelfie=computed(()=>['OWNER','REVIEWER'].includes(adminAccount.value?.role)),canAct=computed(()=>['OWNER','SUPPORT'].includes(adminAccount.value?.role));
const labels={PROFILE_KEYWORD:'프로필 키워드',EXTERNAL_LINK:'외부 링크',FINANCIAL_RISK:'금전·투자 관련',MESSAGE_RISK:'복합 위험 신호',DAILY_REQUEST_LIMIT:'하루 요청 한도 초과',BLOCKED_REGISTRATION:'정지 계정 재가입 시도',PENDING:'셀피 심사 대기',APPROVED:'수동 확인 완료',RETRY:'보완 요청',EXPIRED:'심사 기한 만료'};const date=v=>v?new Date(v).toLocaleString('ko-KR'):'—';
async function load(){error.value='';try{if(mode.value==='events')profiles.value=(await api.get('/admin/safety/users',{params:{riskStatus:'ALL'}})).data||[];rows.value=(await api.get(mode.value==='events'?'/admin/safety/monitor':'/admin/selfies',{params:{open:openOnly.value,page:page.value}})).data;}catch(e){error.value=e.response?.data?.message||'불러오지 못했습니다.';}}
function release(){if(selfie.value)URL.revokeObjectURL(selfie.value);if(reference.value)URL.revokeObjectURL(reference.value);selfie.value=reference.value='';}
function close(){modal.value.close();release();selected.value=null;}
async function select(e){release();selected.value=e;action.value=mode.value==='events'?'NONE':'RETRY';note.value='';modalError.value='';modal.value.showModal();if(mode.value==='selfies'){busy.value=true;try{const photos=await Promise.all([api.get(`/admin/selfies/${e.id}/photo`,{responseType:'blob'}),api.get(`/admin/selfies/${e.id}/photo`,{params:{reference:true},responseType:'blob'})]);if(selected.value?.id!==e.id)return;selfie.value=URL.createObjectURL(photos[0].data);reference.value=URL.createObjectURL(photos[1].data);}catch{modalError.value='사진을 불러오지 못했습니다.';}finally{busy.value=false;}}}
async function save(){if(busy.value)return;busy.value=true;modalError.value='';try{await api.put(mode.value==='events'?`/admin/safety/monitor/${selected.value.id}`:`/admin/selfies/${selected.value.id}`,mode.value==='events'?{note:note.value,action:action.value,days:days.value}:{note:note.value,approve:action.value==='APPROVED'});close();await load();}catch(e){modalError.value=e.response?.data?.message||'저장하지 못했습니다.';}finally{busy.value=false;}}
onMounted(load);onUnmounted(release);
</script><style scoped>
button,select,input,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}.admin-tabs,.admin-toolbar,.pagination{display:flex;gap:12px;align-items:center;margin:14px 0}.admin-tabs button{border:0;padding:12px;background:#eee;border-radius:8px}.admin-tabs .active,.accent{background:#bd7452;color:white}.outlined,.pagination button{background:white;border:1px solid #dce1e7;border-radius:9px;padding:10px 14px}.accent{border:0;border-radius:9px;padding:12px}.subtle{font-size:12px;color:#7e8996}.table-panel{background:white;border:1px solid #e6e9ed;border-radius:12px;overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:16px;text-align:left;border-bottom:1px solid #eee}th{background:#f8f9fb}td small{display:block;margin-top:6px;color:#8a949e}.table-name{border:0;background:none;color:#345}.empty{padding:30px;text-align:center}.pagination{justify-content:center}.admin-dialog{border:0;border-radius:16px;padding:24px;width:min(760px,calc(100% - 32px));max-height:90dvh;overflow:auto}.admin-dialog::backdrop{background:#16233388}.admin-dialog header{display:flex;justify-content:space-between}.icon-close{width:36px;height:36px;flex:none;border:0;background:#eee;border-radius:50%;font-size:24px}.admin-dialog label{display:grid;gap:8px}.admin-dialog select,.admin-dialog input,.admin-dialog textarea{padding:10px;border:1px solid #ddd;border-radius:8px}.case-body{white-space:pre-wrap;overflow-wrap:anywhere;background:#f8f9fb;padding:14px}.admin-dialog p{font-size:13px;line-height:1.7}.detail{white-space:pre-wrap;overflow-wrap:anywhere;min-width:200px;max-width:440px}.compare{display:grid;grid-template-columns:1fr 1fr;gap:12px}.compare figure{margin:0}.compare img{width:100%;height:300px;object-fit:contain;background:#eee}.compare figcaption{font-size:12px}form{display:grid;gap:14px;margin-top:20px}[role=alert]{color:#a33}</style>
